script.segment:
#IF ENAB == 0
! Three Phase Breaker Currents
  #IF View==0
    #OUTPUT REAL IBRA {$CBR:BrA}
    #OUTPUT REAL IBRB {$CBR:BrB}
    #OUTPUT REAL IBRC {$CBR:BrC}
    #OUTPUT REAL IBR0 {ONE_3RD*($CBR:BrA+$CBR:BrB+$CBR:BrC)}
  #ELSE
    #OUTPUT REAL IBRA {$CBR:Br(1)}
    #OUTPUT REAL IBRB {$CBR:Br(2)}
    #OUTPUT REAL IBRC {$CBR:Br(3)}
    #OUTPUT REAL IBR0 {ONE_3RD*($CBR:Br(1)+$CBR:Br(2)+$CBR:Br(3))}
  #ENDIF
#ELSE
!  Breaker and Pre-Post Insertion Resistor Branch Currents
  #IF View==0
    #OUTPUT REAL IBRA {$CBR:BrA + $CBR:BrPA}
    #OUTPUT REAL IBRB {$CBR:BrB + $CBR:BrPB}
    #OUTPUT REAL IBRC {$CBR:BrC + $CBR:BrPC}
    #OUTPUT REAL IBR0 {ONE_3RD*($CBR:BrA+$CBR:BrB+$CBR:BrC+$CBR:BrPA+$CBR:BrPB+$CBR:BrPC)}
  #ELSE
    #OUTPUT REAL IBRA {$CBR:Br(1) + $CBR:BrP(1)}
    #OUTPUT REAL IBRB {$CBR:Br(2) + $CBR:BrP(2)}
    #OUTPUT REAL IBRC {$CBR:Br(3) + $CBR:BrP(3)}
    #OUTPUT REAL IBR0 {ONE_3RD*($CBR:Br(1)+$CBR:Br(2)+$CBR:Br(3)+$CBR:BrP(1)+$CBR:BrP(2)+$CBR:BrP(3))}
  #ENDIF
#ENDIF
#FUNCTION REAL VBRANCH
  #IF View==0
    #OUTPUT REAL Vbr 3 {VBRANCH($SS,$BrA)}{VBRANCH($SS,$BrB)}{VBRANCH($SS,$BrC)}
  #ELSE
    #OUTPUT REAL Vbr 3 {VBRANCH($SS,$Br(1))}{VBRANCH($SS,$Br(2))}{VBRANCH($SS,$Br(3))}
  #ENDIF
#LOCAL INTEGER IVD1_1
#LOCAL REAL RVD1_1
#LOCAL REAL RVD1_2
#STORAGE STOR:12 INTEGER:1
  #IF View==0
      CALL BRK_POWER($SS,$BrA,$BrB,$BrC,
  #ELSE
      CALL BRK_POWER($SS,$Br(1),$Br(2),$Br(3),
  #ENDIF
#IF ENAB==0
     +0,0,0
#ELSE
  #IF View==0
     +$BrPA,$BrPB,$BrPC
  #ELSE
     +$BrP(1),$BrP(2),$BrP(3)
  #ENDIF
#ENDIF
     +,IVD1_1,0.02,RVD1_1,RVD1_2)
#IF DisPQ==1
      IF (UPDATE_AG) THEN
        CALL PSCAD_AGR2(ICALL_NO,$#Component,RVD1_1,"P")
        CALL PSCAD_AGR2(ICALL_NO,$#Component,RVD1_2,"Q")
      ENDIF
#ENDIF
#OUTPUT REAL BP {RVD1_1}
#OUTPUT REAL BQ {RVD1_2}
